import django_rq
from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework import status
from .models import ExportTaskTracker

class AsyncReportExportStatusView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, job_id):
        # Verify that the requested job belongs to the authenticated user via local tracker
        tracker = ExportTaskTracker.objects.filter(job_id=job_id, user=request.user).first()
        if not tracker:
            return Response({'error': 'Job not found or access denied'}, status=status.HTTP_404_NOT_FOUND)

        queue = django_rq.get_queue('exports')
        job = queue.fetch_job(job_id)
        if not job:
            return Response({'error': 'Job not found in queue'}, status=status.HTTP_404_NOT_FOUND)

        response_payload = {
            'job_id': job.id,
            'status': job.get_status(),
            'enqueued_at': job.enqueued_at,
        }
        if job.is_finished:
            response_payload['result'] = job.result

        return Response(response_payload)
